class ReservationStatus(str, Enum):
    """Статус резерва на момент обращения; ``EXPIRED`` вычисляется, а не хранится."""

    ACTIVE = "ACTIVE"
    CONFIRMED = "CONFIRMED"
    CANCELLED = "CANCELLED"
    EXPIRED = "EXPIRED"


@dataclass(frozen=True)
class ReservationLine:
    """Строка резерва: позиция и количество."""

    warehouse: str
    sku: str
    qty: int


@dataclass(frozen=True)
class Reservation:
    """Снимок резерва под заказ."""

    order_id: str
    lines: tuple[ReservationLine, ...]
    status: ReservationStatus
    created_at: datetime
